export function countryName(country) {
  const code = typeof country === 'string' ? country.trim().toUpperCase() : ''
  return Object.hasOwn(COUNTRY_NAMES, code) ? COUNTRY_NAMES[code] : ''
}

export const countries = Object.freeze(Object.keys(FLAGS))

export function flagSource(country, src = '') {
  if (src) return src
  const code = typeof country === 'string' ? country.trim().toUpperCase() : ''
  return /^[A-Z]{2}$/.test(code) && Object.hasOwn(FLAGS, code)
    ? FLAGS[code]
    : ''
}
